begin;
select plan(37);
insert into auth.users(id,is_anonymous) values('a0000000-0000-4000-8000-000000000001',true),('a0000000-0000-4000-8000-000000000002',true),('a0000000-0000-4000-8000-000000000003',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"is_anonymous":true}',true);
select public.create_test_band('Leader','test1234','112233');
select set_config('test.band',public.current_band_identity()->>'band_id',true);
select set_config('test.code',public.band_login_settings()->>'code',true);
select set_config('test.a',(select id::text from public.songs where band_id=current_setting('test.band')::uuid and title like '[테스트 A]%'),true);
select set_config('test.member',public.current_band_identity()->'member'->>'id',true);
select set_config('test.day',((now() at time zone 'Asia/Seoul')::date+10)::text,true);
-- Since 023 only members who saved a date attend it: the leader opts in to the plan days used below.
select public.save_band_availability((select jsonb_agg(jsonb_build_object('date',((now() at time zone 'Asia/Seoul')::date+n)::text)) from generate_series(0,2) n));
select is(jsonb_array_length(public.band_planning_context()->'members'),1,'live context uses current members');
select is((select count(*)::int from public.band_song_votes where song_id=current_setting('test.a')::bigint),1,'sample historical votes sync to live storage');
select ok(not has_function_privilege('authenticated','public.start_round(uuid)','execute'),'manual round start retired');
select ok(not has_function_privilege('authenticated','public.cast_vote(uuid,bigint,text,text)','execute'),'round vote API retired');
select lives_ok($$select public.save_band_availability(jsonb_build_array(jsonb_build_object('date',current_setting('test.day'))))$$,'append a future date');
-- 023 additions are idempotent (concurrent month selections never remove or duplicate a saved day).
select lives_ok($$select public.save_band_availability(jsonb_build_array(jsonb_build_object('date',current_setting('test.day'))))$$,'repeated append is idempotent');
select is((select count(*)::int from public.available_dates where member_id=current_setting('test.member')::uuid and available_date=current_setting('test.day')::date),1,'repeated append keeps one saved row');
select lives_ok($$select public.update_band_availability(current_setting('test.day')::date,current_setting('test.day')::date+1)$$,'change date in saved list');
select is((select count(*)::int from public.available_dates where member_id=current_setting('test.member')::uuid and available_date=current_setting('test.day')::date+1),1,'date edit persists');
select lives_ok($$select public.delete_band_availability(current_setting('test.day')::date+1)$$,'delete saved date individually');
select is((select count(*)::int from public.available_dates where member_id=current_setting('test.member')::uuid),3,'other saved dates retained');
select set_config('test.version',public.band_planning_context()->>'version',true);
select set_config('test.plan',public.save_rehearsal_plan(current_setting('test.band')::uuid,(now() at time zone 'Asia/Seoul')::date,'{}',current_setting('test.version')::bigint,null,null,false)::text,true);
select is((select count(*)::int from public.confirmed_plan_songs where plan_id=current_setting('test.plan')::uuid),0,'date-only confirmation creates no song snapshot');
select throws_ok($$select public.save_rehearsal_plan(current_setting('test.band')::uuid,(now() at time zone 'Asia/Seoul')::date,'{}',current_setting('test.version')::bigint,null,null,false)$$,'P0001','PLANNING_STALE','replayed confirmation rejected');
select lives_ok($$select public.save_rehearsal_plan(current_setting('test.band')::uuid,(now() at time zone 'Asia/Seoul')::date+1,array[current_setting('test.a')::bigint],(public.band_planning_context()->>'version')::bigint,current_setting('test.plan')::uuid,1,false)$$,'add eligible song while editing existing plan');
select is((select count(*)::int from public.confirmed_plans where band_id=current_setting('test.band')::uuid),1,'editing preserves plan identity without consuming a slot');
select is((select version from public.confirmed_plans where id=current_setting('test.plan')::uuid),2,'plan edit increments version');
select is((select count(*)::int from public.confirmed_plan_songs where plan_id=current_setting('test.plan')::uuid),1,'song added to date-only plan');
select throws_ok($$select public.save_rehearsal_plan(current_setting('test.band')::uuid,(now() at time zone 'Asia/Seoul')::date+2,'{}',(public.band_planning_context()->>'version')::bigint,current_setting('test.plan')::uuid,1,false)$$,'P0001','PLAN_STALE','stale plan editor rejected');
select set_config('test.before',public.band_planning_context()->>'version',true);
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000002',true);
select public.begin_band_access(current_setting('test.code'),'test1234');
select public.register_band_profile('New member','bass','246810');
select is(jsonb_array_length(public.band_planning_context()->'members'),2,'new member immediately appears without a round');
select ok((public.band_planning_context()->>'version')::bigint>current_setting('test.before')::bigint,'membership change increments planning version');
select lives_ok($$select public.vote_band_song(current_setting('test.a')::bigint,'yes',null)$$,'new member can vote immediately');
select lives_ok($$select public.save_band_availability(jsonb_build_array(jsonb_build_object('date',current_setting('test.day')),jsonb_build_object('date',((now() at time zone 'Asia/Seoul')::date+2)::text)))$$,'new member can save availability immediately');
select throws_ok($$select public.delete_live_plan(current_setting('test.plan')::uuid,2)$$,'P0001','FORBIDDEN','ordinary member cannot delete plans');
select throws_ok($$select public.save_rehearsal_plan(current_setting('test.band')::uuid,(now() at time zone 'Asia/Seoul')::date,'{}',(public.band_planning_context()->>'version')::bigint,null,null,false)$$,'P0001','FORBIDDEN','ordinary member cannot create plans');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.save_rehearsal_plan(current_setting('test.band')::uuid,(now() at time zone 'Asia/Seoul')::date+2,'{}',current_setting('test.before')::bigint,current_setting('test.plan')::uuid,2,false)$$,'P0001','PLANNING_STALE','member join invalidates open plan editor');
select lives_ok($$select public.save_rehearsal_plan(current_setting('test.band')::uuid,(now() at time zone 'Asia/Seoul')::date+2,'{}',(public.band_planning_context()->>'version')::bigint,current_setting('test.plan')::uuid,2,false)$$,'edit may remove songs and uses new current members');
select is((select participant_count from public.confirmed_plans where id=current_setting('test.plan')::uuid),2,'edited attendance uses current two members');
select is((select count(*)::int from public.confirmed_plan_songs where plan_id=current_setting('test.plan')::uuid),0,'remove songs by editing');
select throws_ok($$select public.save_rehearsal_plan(current_setting('test.band')::uuid,current_setting('test.day')::date,'{}',(public.band_planning_context()->>'version')::bigint,null,null,false)$$,'P0001','PARTIAL_ACK_REQUIRED','partial attendance still requires acknowledgement');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000003',true);
select public.create_code_band('Other band','Other','drums','test1234','123456','654321');
select throws_ok($$select public.vote_band_song(current_setting('test.a')::bigint,'yes',null)$$,'P0001','FORBIDDEN','cross-band vote rejected');
select throws_ok($$select public.delete_live_plan(current_setting('test.plan')::uuid,3)$$,'P0001','FORBIDDEN','other leader cannot delete');
select is((select count(*)::int from public.confirmed_plans),0,'cross-band plan RLS preserved');
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.delete_live_plan(current_setting('test.plan')::uuid,2)$$,'P0001','PLAN_STALE','stale delete cannot remove edited plan');
select lives_ok($$select public.delete_live_plan(current_setting('test.plan')::uuid,3)$$,'owner deletes current plan');
select is((select count(*)::int from public.confirmed_plan_members),0,'plan member snapshots cascade only on deletion');
select ok(not has_function_privilege('anon','public.save_rehearsal_plan(uuid,date,bigint[],bigint,uuid,integer,boolean)','execute'),'unauthenticated API role cannot create plans');
select ok(not has_function_privilege('authenticated','public.save_unavailability(uuid,jsonb,boolean)','execute'),'round replacement availability API retired');
select * from finish();rollback;
